    public int primeSubSequence(int N) {
        int[] a = new int[N];
        Arrays.fill(a, 1);

        int i = 2;
        while (a[N - 1] < N) {
            int j = a[N - 1];
            while(j >= i) --j;
            a[--j] = i++;
        }

        return a[N - 1];
    }    
